changeSet.sql:
DO $$
BEGIN
	IF to_regclass('roles') IS NULL THEN
		RAISE EXCEPTION 'Cannot convert legacy role_id references: the roles master table is missing.';
	END IF;
	IF EXISTS (
		SELECT 1 FROM roles
		WHERE upper(btrim(slug)) NOT IN ('FIGHTER', 'ASSASSIN', 'MAGE', 'MARKSMAN', 'TANK', 'SUPPORT')
	) OR EXISTS (
		SELECT 1 FROM roles GROUP BY upper(btrim(slug)) HAVING count(*) > 1
	) THEN
		RAISE EXCEPTION 'Resolve unsupported or duplicate normalized role slugs before converting to enums.';
	END IF;
END $$;

DO $$
BEGIN
	IF to_regclass('lanes') IS NULL THEN
		RAISE EXCEPTION 'Cannot convert legacy lane_id references: the lanes master table is missing.';
	END IF;
	IF EXISTS (
		SELECT 1 FROM lanes
		WHERE upper(btrim(slug)) NOT IN ('CLASH', 'JUNGLE', 'MID', 'FARM', 'ROAM')
	) OR EXISTS (
		SELECT 1 FROM lanes GROUP BY upper(btrim(slug)) HAVING count(*) > 1
	) THEN
		RAISE EXCEPTION 'Resolve unsupported or duplicate normalized lane slugs before converting to enums.';
	END IF;
END $$;

DROP INDEX IF EXISTS idx_hero_roles_lower_role_hero;
DROP INDEX IF EXISTS idx_hero_lanes_lower_lane_hero;
CREATE INDEX IF NOT EXISTS idx_hero_roles_role_hero ON hero_roles (role, hero_id);
CREATE INDEX IF NOT EXISTS idx_hero_lanes_lane_hero ON hero_lanes (lane, hero_id);
ALTER TABLE hero_roles DROP CONSTRAINT IF EXISTS chk_hero_roles_role;
ALTER TABLE hero_roles ADD CONSTRAINT chk_hero_roles_role
	CHECK (role IN ('FIGHTER', 'ASSASSIN', 'MAGE', 'MARKSMAN', 'TANK', 'SUPPORT'));
ALTER TABLE hero_lanes DROP CONSTRAINT IF EXISTS chk_hero_lanes_lane;
ALTER TABLE hero_lanes ADD CONSTRAINT chk_hero_lanes_lane
	CHECK (lane IN ('CLASH', 'JUNGLE', 'MID', 'FARM', 'ROAM'));
DROP TABLE IF EXISTS roles;
DROP TABLE IF EXISTS lanes;
